        /// <summary>
        /// Apply schema and file upgrades to the storage object.
        /// </summary>
        /// <exception cref="InvalidDataException">The storage backend is in a corrupted state.</exception>
        internal void DoUpgrades()
        {
            Logger.Info("BCC589B56D2I Beginning database schema upgrade.");
            try
            {
                // Resolve the assets directory relative to the application base.
                string? assdir = GetThisDir("assets");
                if (assdir == null) return;

                // Perform all upgrade steps within a single transaction.
                using (var transaction = m_conn.BeginTransaction())
                {
                    // Ensure the 'properties' table exists.
                    if (m_conn.Syntax() == DbTools.Extensions.SqlSyntax.SqlServer)
                    {
                        // SQL Server specific syntax.
                        m_conn.Execute("IF OBJECT_ID('properties') IS NULL BEGIN CREATE TABLE properties(name NVARCHAR(255) PRIMARY KEY, value TEXT) END", transaction: transaction);
